                "I Settimana del Tempo di Pasqua",
                "Dell'amore del Signore è piena la terra.",
                "Feria nell'Ottava di Pasqua - BIANCO - Messa propria del martedì nell'Ottava di Pasqua. Si dicono il Gloria e il Credo. Nelle Preghiere Eucaristiche dove è previsto, si usano le parti proprie della domenica di Pasqua.",
