                "I Settimana del Tempo di Pasqua",
                "O Signore, Signore nostro, quanto è mirabile il tuo nome su tutta la terra!",
                "Feria nell'Ottava di Pasqua - BIANCO - Messa propria del giovedì nell'Ottava di Pasqua. Si dicono il Gloria e il Credo. Nelle Preghiere Eucaristiche dove è previsto, si usano le parti proprie della domenica di Pasqua.",
