                "I Settimana del Tempo di Pasqua",
                "La pietra scartata dai costruttori è divenuta la pietra d'angolo.",
                "Feria nell'Ottava di Pasqua - BIANCO - Messa propria del venerdì nell'Ottava di Pasqua. Si dicono il Gloria e il Credo. Nelle Preghiere Eucaristiche dove è previsto, si usano le parti proprie della domenica di Pasqua.",
