            "14": [
                "Venerdì",
                "I Settimana del Tempo di Quaresima",
                "Se consideri le colpe, Signore, chi ti può resistere?",
                "Feria aliturgica - Venerdì di Quaresima: tutti i venerdì di Quaresima secondo la tradizione ambrosiana sono giorni aliturgici, cioè privi di liturgia eucaristica. È proibita la celebrazione di qualsiasi Messa e non si distribuisce l’Eucaristia, salvo il caso del S. Viatico per chi versa in pericolo di morte. I presbiteri di Rito Ambrosiano non si rechino a celebrare in una parrocchia di Rito Romano salvo il caso di una grave necessità pastorale. Tutti i venerdì di Quaresima sono giorni di astinenza dalle carni. Il primo venerdì di Quaresima e il venerdì della Settimana Autentica sono anche giorni di digiuno, nelle forme prescritte dalla Chiesa. - Via Crucis: durante i venerdì di Quaresima può opportunamente trovare spazio la celebrazione della Via Crucis (si usano i paramenti di colore rosso) - Liturgia Vespertina: i Vespri dei venerdì di Quaresima presentano una struttura celebrativa simile a quella delle grandi liturgie vigiliare, con quattro letture dell’Antico Testamento. Secondo l’opportunità pastorale, la celebrazione dei Vespri avvenga con la partecipazione del popolo.",
                "",
                "Ez 18, 21-28|Sal 129|Mt 5, 20-26",
                "Dt 1,3-11|1Sam 12,1-11|Es 3,1-12"
            ],
