                "Giovedì",
                "Giovedì Santo",
                "Il tuo calice, Signore, è dono di salvezza.",
                "Feria nella Settimana Autentica – ROSSO - Secondo un’antichissima tradizione, in questo giorno sono vietate tutte le Messe senza partecipazione del popolo. Il mattino, in Cattedrale, l’Arcivescovo celebra la Messa Crismale, che è concelebrata da tutto il clero diocesano. Secondo l’opportunità pastorale, nelle singole parrocchie si può celebrare una Liturgia della Parola ordinata come segue.",
                "",
                "Es 12, 1-8. 11-14|Sal 115|1Cor 11, 23-26|Gv 13, 1-15",
                "Dn 13,1-64 oppure Dn 6,2-29|Sap 2,1a.12-3,9|Dalla mattina di questo giorno e per tutto il Triduo Pasquale sono proibite tutte le Messe per i defunti, inclusa la Messa esequiale. Qualora si debbano celebrare le esequie, senza Messa, il rito si dovrà compiere senza solennità."
