                "Domenica di Pasqua della Risurrezione",
                "Questo è il giorno che ha fatto il Signore: rallegriamoci ed esultiamo.",
                "DOMENICA DI PASQUA, NELLA RISURREZIONE DEL SIGNORE (solennità) – BIANCO - Messa propria del giorno. Si dicono il Gloria e il Credo. Nelle preghiere eucaristiche che le prevedono si usano le parti proprie della solennità di Pasqua.",
